@CrossOrigin
@RestController
@RequestMapping("/DepartmentQuery")
public class DepartmentQueryRestController extends BaseSpringRestController {
	
	public DepartmentQueryRestController( DepartmentService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Department using a UUID
     * @param		UUID departmentId
     * @return		Department
     */    
    @GetMapping("/load")
    public Department load( @RequestParam(required=true) UUID departmentId ) {
    	Department entity = null;

    	try {  
    		entity = service.getDepartment( new DepartmentFetchOneSummary( departmentId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Department using Id " + departmentId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Department business objects
     * @return		Set<Department>
     */
    @GetMapping("/")
    public List<Department> loadAll() {                
    	List<Department> departmentList = null;
        
    	try {
            // load the Department
            departmentList = service.getAllDepartment();
            
            if ( departmentList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Departments" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Departments ", exc );
        	return null;
        }

        return departmentList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Department department = null;
    protected DepartmentService service = null;
    private static final Logger LOGGER = Logger.getLogger(DepartmentQueryRestController.class.getName());
    
}
